  + "scope: 'work', description: 'd', why: 'w', run: () => [{ rule: 'always-fails', severity: 'blocking', file: 'a.txt', "
  + "line: null, what: 'deliberate', why: 'w', fix: 'f', doc: null }] }] };\n";

